// Reservations.
// Owner: Agent B1 (see docs/architecture/MODULE_CONTRACTS.md). Other agents
// import from here but do not edit this file.
import { z } from 'zod';
import { idempotencyKey, isoDate, optionalPhone, optionalText, uuid } from './common';
import { guestPhone } from './phone';
import { TABLE_FEATURES } from './floor';

export const reservationsContractsVersion = 2 as const;

/** Legacy rules (server.js): 5-minute hold, check-in −15/+30 minutes, bookings up to 180 days ahead. */
export const RESERVATION_RULES = {
  holdMinutes: 5,
  depositWindowMinutes: 15,
  checkInBeforeMinutes: 15,
  checkInAfterMinutes: 30,
  maxDaysAhead: 180,
} as const;

const hhmm = z.string().regex(/^([01]\d|2[0-3]):[0-5]\d$/, 'HH:MM');

export const availabilityQuery = z.object({
  branch: z.string().max(60).optional(),     // branch code (public) …
  branchId: uuid.optional(),                 // … or id (staff)
  date: isoDate,
  time: hhmm,
  partySize: z.coerce.number().int().min(1).max(50),
  features: z.string().max(400).optional(), // comma separated TABLE_FEATURES
});
export type AvailabilityQuery = z.infer<typeof availabilityQuery>;

export const reservationHoldRequest = z.object({
  branchId: uuid,
  tableId: uuid.optional(),                  // omit to let the server pick the best fitting table
  date: isoDate,
  time: hhmm,
  partySize: z.number().int().min(1).max(50),
  guestName: z.string().trim().min(1).max(100),
  /** As typed (local EG/SA forms, Arabic-Indic digits); the API stores E.164 for the restaurant's country (CR-06). */
  guestPhone: guestPhone,
  guestEmail: z.email().max(200).optional().nullable(),
  notes: optionalText(500),
  features: z.array(z.enum(TABLE_FEATURES)).max(13).optional(),
  key: idempotencyKey,
});
export type ReservationHoldRequest = z.infer<typeof reservationHoldRequest>;

export const reservationConfirmRequest = z.object({ key: idempotencyKey, returnUrl: z.url().max(500).optional() });

export const staffReservationInput = z.object({
  branchId: uuid,
  tableId: uuid.optional().nullable(),
  date: isoDate,
  time: hhmm,
  partySize: z.number().int().min(1).max(50),
  guestName: z.string().trim().min(1).max(100),
  guestPhone: optionalPhone(30),
  guestEmail: z.email().max(200).optional().nullable(),
  notes: optionalText(500),
  durationMinutes: z.number().int().min(15).max(600).optional(),
  source: z.enum(['staff', 'phone', 'whatsapp']).default('staff'),
  /** Staff may require the branch deposit (creates a pending_deposit booking) or waive it (default). */
  requireDeposit: z.boolean().default(false),
});
export const staffReservationUpdate = z.object({
  tableId: uuid.optional().nullable(),
  date: isoDate.optional(),
  time: hhmm.optional(),
  partySize: z.number().int().min(1).max(50).optional(),
  guestName: z.string().trim().min(1).max(100).optional(),
  guestPhone: optionalPhone(30),
  notes: optionalText(500),
  durationMinutes: z.number().int().min(15).max(600).optional(),
});
export const reservationCancelRequest = z.object({ reason: optionalText(300) });
export const reservationDayQuery = z.object({ branchId: uuid.optional(), date: isoDate, status: z.string().max(200).optional() });

export interface AvailabilityTable {
  id: string; label: string; capacity: number; zone: string | null; features: string[]; premium: boolean; minSpendMinor: number | null;
  available: boolean; reason: null | 'too_small' | 'not_reservable' | 'booked' | 'occupied' | 'cleaning' | 'out_of_service' | 'missing_features';
  /** false when the table lacks one of the requested features (it is then not available). */
  matchesFeatures: boolean;
}
export interface AvailabilityResult {
  branchId: string; startsAt: string; endsAt: string; blockedUntil: string; open: boolean; closedReason: string | null;
  depositMinor: number; currency: string; tables: AvailabilityTable[];
  /** Alternative start times (same day, ±2 h) with at least one fitting table, when the requested time has none. */
  alternatives: string[];
}

export interface ReservationView {
  id: string; code: string; branchId: string; tableId: string | null; tableLabel: string | null; status: string;
  guestName: string; guestPhone: string | null; guestEmail: string | null; partySize: number; startsAt: string; endsAt: string;
  holdExpiresAt: string | null; depositMinor: number; depositStatus: string; source: string; notes: string | null;
  seatedVisitId: string | null; currency: string; createdAt: string;
}
/** Public hold response: the manage token is shown once. */
export interface ReservationHoldResult { reservation: ReservationView; manageToken: string }
